Deno.serve(async (_req) => {
  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  // Ensure company + profile
  const { data: prof } = await supabase.from("profiles").select("company_id").eq("id", USER_ID).maybeSingle();
  let companyId = prof?.company_id as string | null;
  if (!companyId) {
    const { data: co, error: ce } = await supabase.from("companies").insert({ name: "Default Company" }).select("id").single();
    if (ce) return new Response(JSON.stringify({ error: ce.message }), { status: 500 });
    companyId = co.id;
    await supabase.from("profiles").upsert({ id: USER_ID, company_id: companyId, role: "planner" });
  }

  await supabase.from("skus").delete().eq("user_id", USER_ID);

  const enriched = ROWS.map((r: any) => ({ ...r, user_id: USER_ID, company_id: companyId }));
  const chunkSize = 200;
  let inserted = 0;
  for (let i = 0; i < enriched.length; i += chunkSize) {
    const chunk = enriched.slice(i, i + chunkSize);
    const { error } = await supabase.from("skus").insert(chunk);
    if (error) return new Response(JSON.stringify({ error: error.message, at: i }), { status: 500 });
    inserted += chunk.length;
  }

  return new Response(JSON.stringify({ inserted, companyId }), { headers: { "content-type": "application/json" } });
});
